"use client";

import { useState } from "react";

export function SpotlightGradientTailwind({ children }: { children?: React.ReactNode }) {
  const [pos, setPos] = useState({ x: 50, y: 45 });
  const at = pos.x + "% " + pos.y + "%";
  return (
    <div
      onPointerMove={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        setPos({ x: ((e.clientX - r.left) / r.width) * 100, y: ((e.clientY - r.top) / r.height) * 100 });
      }}
      className="relative isolate flex h-[360px] w-full items-center justify-center overflow-hidden rounded-[20px] border border-zinc-800 bg-[#09090f]"
    >
      <div aria-hidden className="absolute inset-0 opacity-15 [background-image:radial-gradient(circle,#fff_1px,transparent_1.6px)] [background-size:22px_22px]" />
      <div aria-hidden className="absolute inset-0" style={{ background: "radial-gradient(circle 140px at " + at + ", rgba(34,211,238,0.5), transparent), radial-gradient(circle 320px at " + at + ", rgba(139,92,246,0.4), transparent)" }} />
      <div className="relative text-center">
        {children ?? (
          <>
            <h3 className="text-3xl font-bold tracking-tight text-zinc-50">Spotlight Gradient</h3>
            <p className="mt-2 text-sm text-zinc-400">Move your cursor to steer the light across the grid.</p>
          </>
        )}
      </div>
    </div>
  );
}
